import "sync"
type Future struct { once sync.Once; done chan struct{}; value int }
func NewFuture() *Future { return &Future{done: make(chan struct{})} }
func (f *Future) Resolve(value int) {
    f.once.Do(func() { f.value = value; close(f.done) })
}
func (f *Future) Get() int { <-f.done; return f.value }

func HalfSync(frames <-chan int, write func(int)) {
    jobs := make(chan int, 2)
    done := make(chan struct{})
    go func() {
        for frame := range jobs { write(frame * frame) }
        close(done)
    }()
    for frame := range frames { jobs <- frame }
    close(jobs); <-done
}

import ("context"; "sync")
type Outcome struct { value int; err error }
func Scope(a, b func(context.Context) (int, error)) (int, error) {
    ctx, cancel := context.WithCancel(context.Background()); defer cancel()
    out := make(chan Outcome, 2)
    var wg sync.WaitGroup
    for _, fn := range []func(context.Context)(int,error){a,b} {
        wg.Add(1)
        go func(f func(context.Context)(int,error)) {
            defer wg.Done(); v,e := f(ctx); out <- Outcome{v,e}
        }(fn)
    }
    total := 0; var first error
    for i:=0; i<2; i++ {
        r := <-out
        if r.err != nil && first == nil { first = r.err; cancel() }
        total += r.value
    }
    wg.Wait(); return total, first
}

func Supervise(run func() error) error {
    for attempt:=0; attempt<2; attempt++ {
        done := make(chan error, 1)
        go func() { done <- run() }()
        err := <-done
        if err == nil { return nil }
        if attempt == 1 { return err }
    }
    return nil
}

import "sync"
func MapReduce(parts [][]int) map[int]int {
    keys := make(chan int)
    var wg sync.WaitGroup
    for _, part := range parts {
        wg.Add(1)
        go func(xs []int) {
            defer wg.Done()
            for _, x := range xs { keys <- x % 2 }
        }(part)
    }
    go func(){ wg.Wait(); close(keys) }()
    totals := map[int]int{0:0,1:0}
    for key := range keys { totals[key]++ }
    return totals
}

type AskReply struct { Token int64; Value int }
type AskEvent struct { Kind int; Token int64; Value int; Reply AskReply }
type AskPorts struct {
    Compute func(int64, int)
    Schedule func(int64)
    Finished func(int64, bool, int)
    Rejected func(int)
    Status func(bool, int64)
}
func RunAsk(in <-chan AskEvent, p AskPorts) {
    var next, current int64
    active := false
    for event := range in {
        switch event.Kind {
        case 0:
            if active { p.Rejected(1); continue }
            if next == 9223372036854775807 { p.Rejected(2); continue }
            next++; current = next; active = true
            p.Schedule(current)
            p.Compute(current, event.Value)
        case 1:
            if active && event.Reply.Token == current {
                active = false
                p.Finished(current, false, event.Reply.Value)
            }
        case 2:
            if active && event.Token == current {
                active = false
                p.Finished(current, true, 0)
            }
        case 3:
            p.Status(active, current)
        }
    }
}
func DoubleReply(token int64, value int) AskReply {
    return AskReply{Token: token, Value: value * 2}
}

type StashEvent struct { Kind, ID, Value, Mode int }
func RunSelective(in <-chan StashEvent, emit func(string, int, int)) {
    phase := 0
    queue := make([]StashEvent, 0, 2)
    wake := make(chan struct{}, 1)
    pump := func() { select { case wake <- struct{}{}: default: } }
    for {
        select {
        case event, open := <-in:
            if !open { return }
            switch event.Kind {
            case 0:
                if phase == 2 { emit("rejected", event.ID, 2); continue }
                if phase == 1 && len(queue) == 0 {
                    emit("finished", event.ID, event.Value * 2); continue
                }
                if len(queue) == 2 { emit("rejected", event.ID, 1); continue }
                queue = append(queue, event)
                if phase == 1 { pump() }
            case 1:
                if phase != 2 && event.Mode >= 0 && event.Mode <= 1 {
                    phase = event.Mode
                    if phase == 1 && len(queue) > 0 { pump() }
                }
            case 2:
                emit("reply", event.ID, event.Value)
            case 3:
                emit("status", phase, len(queue))
            case 4:
                if phase == 2 { continue }
                phase = 2
                for _, item := range queue { emit("rejected", item.ID, 2) }
                queue = queue[:0]
                emit("stopped", 0, 0)
            }
        case <-wake:
            if phase != 1 || len(queue) == 0 { continue }
            item := queue[0]; queue = queue[1:]
            emit("finished", item.ID, item.Value * 2)
            if len(queue) > 0 { pump() }
        }
    }
}

type PhaseEvent struct { Kind, Child, Value int; Epoch int64; OK bool }
type ParentPorts struct {
    Drain func(int, int64)
    CloseChildren func(int64)
    CloseOwner func()
    Finished func(bool)
    Status func(int, int, int)
}
func RunPhaseParent(in <-chan PhaseEvent, epoch int64, p ParentPorts) {
    phase, drain, stop := 0, 2, 2
    failed := false
    var drained, stopped [2]bool
    for e := range in {
        switch e.Kind {
        case 0:
            if phase != 0 { continue }
            phase = 1; p.Drain(0, epoch); p.Drain(1, epoch)
        case 1:
            if phase != 1 || e.Epoch != epoch || e.Child < 0 || e.Child > 1 || drained[e.Child] { continue }
            drained[e.Child] = true; failed = failed || !e.OK; drain--
            if drain == 0 { phase = 2; p.CloseChildren(epoch) }
        case 2:
            if phase != 2 || e.Epoch != epoch || e.Child < 0 || e.Child > 1 || stopped[e.Child] { continue }
            stopped[e.Child] = true; stop--
            if stop == 0 { phase = 3; p.Finished(!failed); p.CloseOwner() }
        case 3:
            p.Status(phase, drain, stop)
        }
    }
}
type ChildPorts struct {
    Flush func(int64)
    ReleaseCompleted func()
    Drained func(int, int64, bool)
    Value func(int)
    Rejected func()
    Status func(int, int)
}
func RunPhaseChild(in <-chan PhaseEvent, id int, epoch int64, p ChildPorts) {
    phase := 0
    for e := range in {
        switch e.Kind {
        case 0:
            if phase != 0 { p.Rejected() } else { p.Value(e.Value * 2) }
        case 1:
            if phase == 0 && e.Epoch == epoch { phase = 1; p.Flush(epoch) }
        case 2:
            if phase == 1 && e.Epoch == epoch {
                p.ReleaseCompleted(); phase = 2; p.Drained(id, epoch, e.OK)
            }
        case 3:
            p.Status(id, phase)
        }
    }
}

type BlockingEvent struct { Kind, Value int }
type BlockingResult struct { Token int64; OK bool; Value int }
func RunBlocking(in <-chan BlockingEvent, call func(int) (int, error),
    emit func(string, int64, bool, int), releaseIdle func()) {
    done := make(chan BlockingResult, 1)
    var next int64
    active, closing := false, false
    finish := func() { releaseIdle(); emit("closed", 0, true, 0) }
    for {
        select {
        case e, open := <-in:
            if !open { in = nil; closing = true; if !active { finish(); return }; continue }
            switch e.Kind {
            case 0:
                if active || closing { emit("rejected", 0, false, 1); continue }
                if next == 9223372036854775807 { emit("rejected", 0, false, 2); continue }
                next++; active = true
                go func(token int64, value int) {
                    result := BlockingResult{Token: token}
                    defer func() { if recover() != nil { result.OK = false }; done <- result }()
                    v, err := call(value)
                    result.OK, result.Value = err == nil, v
                }(next, e.Value)
            case 1:
                closing = true
                if !active { finish(); return }
            case 2:
                emit("status", next, active, map[bool]int{false:0,true:1}[closing])
            }
        case result := <-done:
            if !active || result.Token != next { continue }
            active = false
            emit("finished", result.Token, result.OK, result.Value)
            if closing { finish(); return }
        }
    }
}

blocking_client(Call, ReleaseIdle, Observer) ->
    blocking_loop(Call, ReleaseIdle, Observer, 0, false, false).
blocking_loop(Call, ReleaseIdle, Observer, Token, Active, Closing) ->
    receive
        {submit, _} when Active; Closing ->
            Observer ! {rejected, 1},
            blocking_loop(Call,ReleaseIdle,Observer,Token,Active,Closing);
        {submit, _} when Token =:= 9223372036854775807 ->
            Observer ! {rejected, 2},
            blocking_loop(Call,ReleaseIdle,Observer,Token,Active,Closing);
        {submit, Value} ->
            Next = Token+1, Parent = self(),
            spawn(fun() ->
                Result = try Call(Value) of V -> {true,V}
                         catch _:_ -> {false,0} end,
                Parent ! {completed, Next, Result}
            end),
            blocking_loop(Call,ReleaseIdle,Observer,Next,true,Closing);
        {completed, Token, {OK, Value}} when Active ->
            Observer ! {finished, Token, OK, Value},
            case Closing of
                true -> ReleaseIdle(), Observer ! closed, ok;
                false -> blocking_loop(Call,ReleaseIdle,Observer,Token,false,false)
            end;
        begin_close when Active ->
            blocking_loop(Call,ReleaseIdle,Observer,Token,true,true);
        begin_close ->
            ReleaseIdle(), Observer ! closed, ok;
        query ->
            Observer ! {status, Closing, Active},
            blocking_loop(Call,ReleaseIdle,Observer,Token,Active,Closing);
        _ -> blocking_loop(Call,ReleaseIdle,Observer,Token,Active,Closing)
    end.
